-- Criar tabela tenants
CREATE TABLE IF NOT EXISTS tenants (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(128) NOT NULL,
  slug VARCHAR(64) NOT NULL UNIQUE,
  adminEmail VARCHAR(320) NOT NULL,
  plano ENUM('trial','basico','pro') NOT NULL DEFAULT 'trial',
  ativo INT NOT NULL DEFAULT 1,
  createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL
);

-- Inserir o tenant do Barbiero Grupo (id=1)
INSERT INTO tenants (id, nome, slug, adminEmail, plano, ativo)
VALUES (1, 'Barbiero Grupo', 'barbiero-grupo', 'cassiano@barbierogrupo.com', 'pro', 1)
ON DUPLICATE KEY UPDATE nome=nome;

-- Adicionar tenantId nas tabelas existentes
ALTER TABLE users ADD COLUMN IF NOT EXISTS tenantId INT DEFAULT 1;
ALTER TABLE userEmpresas ADD COLUMN IF NOT EXISTS tenantId INT NOT NULL DEFAULT 1;
ALTER TABLE accessLogs ADD COLUMN IF NOT EXISTS tenantId INT DEFAULT 1;
ALTER TABLE empresas ADD COLUMN IF NOT EXISTS tenantId INT NOT NULL DEFAULT 1;
ALTER TABLE bonificacoes ADD COLUMN IF NOT EXISTS tenantId INT NOT NULL DEFAULT 1;
ALTER TABLE categorias ADD COLUMN IF NOT EXISTS tenantId INT NOT NULL DEFAULT 1;
ALTER TABLE metas ADD COLUMN IF NOT EXISTS tenantId INT NOT NULL DEFAULT 1;
ALTER TABLE faturamentos ADD COLUMN IF NOT EXISTS tenantId INT NOT NULL DEFAULT 1;

-- Remover unique constraint antiga de empresas (slug era único globalmente, agora é único por tenant)
ALTER TABLE empresas DROP INDEX IF EXISTS empresas_slug_unique;

